mkdir -p /tmp/probe/reports && cat > /tmp/probe/argv.mjs <<'EOF'
import {execFile} from 'node:child_process';
import {readFileSync} from 'node:fs';
const EXE='/workspace/dataset/test4_executable';
const cases=JSON.parse(readFileSync(process.argv[2],'utf8'));
const conc=parseInt(process.argv[3]||'8',10);
const out=new Array(cases.length);
let i=0;
function run1(idx){return new Promise(res=>{
  const c=cases[idx];
  const argv=Array.isArray(c)?c:c.argv;
  const env=(c&&c.env)?{...process.env,...c.env}:process.env;
  execFile(EXE,argv,{env,encoding:'buffer',maxBuffer:1<<26,timeout:20000},(err,so,se)=>{
    res({i:idx,argv,rc:err?(err.code===undefined?('sig:'+err.signal):err.code):0,
      out:so.toString('utf8'),err:se.toString('utf8')});
  });});}
async function worker(){while(true){const k=i++;if(k>=cases.length)return;out[k]=await run1(k);}}
await Promise.all(Array.from({length:conc},worker));
console.log(JSON.stringify(out,null,1));
EOF
echo ok
